begin;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
update cozinha_preparacoes set ativo=false,observacao=coalesce(observacao,'') || ' | Arquivado: importação antiga sem uso; preparação completa já cadastrada.' where nome in ('Empanamento • TD08','Empanamento • TD17','Molho demi glace') and not exists(select 1 from cozinha_receita_itens r where r.preparacao_id=cozinha_preparacoes.id) and not exists(select 1 from cozinha_preparacao_itens x where x.preparacao_componente_id=cozinha_preparacoes.id);
update cozinha_preparacao_itens x set quantidade=case i.nome when 'Calabresa' then 800 when 'Paio' then 800 else x.quantidade end, quantidade_texto=case i.nome when 'Calabresa' then '800 g de calabresa — proporção da ficha TD15 (20 g para 50 g de feijão seco); pesar as 4 unidades' when 'Paio' then '800 g de paio — proporção da ficha TD15 (20 g para 50 g de feijão seco); pesar as 3 unidades' else x.quantidade_texto end from cozinha_ingredientes i,cozinha_preparacoes p where x.ingrediente_id=i.id and x.preparacao_id=p.id and p.nome='Feijoada' and i.nome in ('Calabresa','Paio');
insert into cozinha_preparacao_itens(preparacao_id,ingrediente_id,quantidade,quantidade_texto,ordem) select p.id,i.id,6,'6 L de água para cocção de 2 kg de feijão; o rendimento conta a hidratação uma vez',8 from cozinha_preparacoes p,cozinha_ingredientes i where p.nome='Feijoada' and i.nome='Água' and not exists(select 1 from cozinha_preparacao_itens x where x.preparacao_id=p.id and x.ingrediente_id=i.id);
update cozinha_preparacoes set rendimento_final_g=9924,observacao='Base original TD15 com quantidades em gramas. Calabresa e paio proporcionais à gramatura da ficha. Rendimento teórico: feijão 3x, calabresa e bacon -10%, costela suína -30%. Água de hidratação contada uma vez. Pesar o lote final para calibrar evaporação e pesar as unidades de embutidos.' where nome='Feijoada';
insert into cozinha_preparacao_itens(preparacao_id,ingrediente_id,quantidade,quantidade_texto,ordem) select p.id,i.id,v.q,v.texto,v.ordem from cozinha_preparacoes p cross join (values ('Aipim',1000::numeric,'1 kg de mandioca descascada — ficha original TD07',0),('Margarina',15::numeric,'15 g de margarina — aproximadamente 1 colher da ficha original',1),('Água',0.2::numeric,'0,2 L de água de cocção retida no purê — base proporcional à ficha 107 g de aipim para 130 g prontos',2),('Sal',0::numeric,'QB — acertar sal',3)) v(nome,q,texto,ordem) join cozinha_ingredientes i on i.nome=v.nome where p.nome='Purê de mandioca' and not exists(select 1 from cozinha_preparacao_itens x where x.preparacao_id=p.id and x.ingrediente_id=i.id);
update cozinha_preparacoes set rendimento_final_g=1215,observacao='Ficha original TD07: 1 kg de mandioca descascada, água retida e 1 colher de margarina (~15 g). Rendimento teórico proporcional à gramatura cadastrada: 107 g de aipim para 130 g de purê. Pesar o lote final para calibrar água/evaporação.' where nome='Purê de mandioca';
update cozinha_preparacao_itens x set quantidade=case i.nome when 'Calabresa' then 1000 when 'Cenoura' then 666.667 when 'Tomate' then 333.333 else x.quantidade end,quantidade_texto=case i.nome when 'Calabresa' then '1 kg — proporção da ficha TD05: bacon 30 g / calabresa 30 g; pesar as 4 unidades' when 'Cenoura' then '666,667 g — proporção da ficha TD05: bacon 30 g / cenoura 20 g; pesar as 4 unidades' when 'Tomate' then '333,333 g — proporção da ficha TD05: bacon 30 g / tomate 10 g; pesar as 2 unidades' else x.quantidade_texto end from cozinha_ingredientes i,cozinha_preparacoes p where x.ingrediente_id=i.id and x.preparacao_id=p.id and p.nome='Carreteiro' and i.nome in ('Calabresa','Cenoura','Tomate');
insert into cozinha_preparacao_itens(preparacao_id,ingrediente_id,quantidade,quantidade_texto,ordem) select p.id,i.id,7.5,'7,5 L de água para 3 kg de arroz; hidratação contada uma vez no rendimento',8 from cozinha_preparacoes p,cozinha_ingredientes i where p.nome='Carreteiro' and i.nome='Água' and not exists(select 1 from cozinha_preparacao_itens x where x.preparacao_id=p.id and x.ingrediente_id=i.id);
update cozinha_preparacoes set rendimento_final_g=13526.334,observacao='Base original TD05: arroz 3 kg, bacon 1 kg e carne desfiada 1,5 kg. Calabresa, cenoura e tomate convertidos para gramas conforme proporções da ficha de custos. Rendimento teórico: arroz 2,9x; perdas cadastradas dos demais ingredientes; água de hidratação contada uma vez. Pesar unidades e lote pronto para calibrar.' where nome='Carreteiro';
commit;
